// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts Every account, staff first, then by name
	// (GET /accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// InviteAccount Add a person from the tenant registry and email them an invitation
	// (POST /accounts)
	InviteAccount(ctx context.Context, request InviteAccountRequestObject) (InviteAccountResponseObject, error)
	// ImportAccounts Invite residents from the tenant registry in one go (at launch). Rows that fail are reported, not fatal.
	// (POST /accounts/import)
	ImportAccounts(ctx context.Context, request ImportAccountsRequestObject) (ImportAccountsResponseObject, error)
	// DeactivateAccount Deactivate an account when the tenancy ends; signs it out everywhere
	// (POST /accounts/{account_id}/deactivate)
	DeactivateAccount(ctx context.Context, request DeactivateAccountRequestObject) (DeactivateAccountResponseObject, error)
	// ReinviteAccount Send a new invitation link; the previous link stops working
	// (POST /accounts/{account_id}/reinvite)
	ReinviteAccount(ctx context.Context, request ReinviteAccountRequestObject) (ReinviteAccountResponseObject, error)
	// SetAccountRole Change an account's role; applies on its next request
	// (PUT /accounts/{account_id}/role)
	SetAccountRole(ctx context.Context, request SetAccountRoleRequestObject) (SetAccountRoleResponseObject, error)
	// Login Sign in with email and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Sign out this device
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ForgotPassword Email a password reset link (always 202, whether or not the email has an account)
	// (POST /auth/password/forgot)
	ForgotPassword(ctx context.Context, request ForgotPasswordRequestObject) (ForgotPasswordResponseObject, error)
	// InspectPasswordToken Who an invitation or reset link is for (the token is sent in the body, not the URL)
	// (POST /auth/password/inspect)
	InspectPasswordToken(ctx context.Context, request InspectPasswordTokenRequestObject) (InspectPasswordTokenResponseObject, error)
	// SetPassword Set a password with an invitation or reset link, then sign in
	// (POST /auth/password/set)
	SetPassword(ctx context.Context, request SetPasswordRequestObject) (SetPasswordResponseObject, error)
	// GetMe The signed-in account, its permissions and the CSRF token
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ChangePassword Change your own password; your other devices are signed out
	// (PUT /me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

